Given two integers n and k. Implement k stacks using a single array of size n. Multiple stacks must share the same array space while supporting the following operations:push(x, i): Push element x into the i-th stack.pop(i): Pop the top element from the i-th stack and return it.Try It YourselfTable of Content[Naive Approach] Dividing Array into k Segments[Efficient Approach] Using Space Optimized Method[Naive Approach] Dividing Array into k SegmentsThe idea is to divide the array into fixed parts, one for each stack. If the array size is n and there are k stacks, then each stack gets n/k slots.We maintain another array top[] of size k, where top[i] stores the index of the top element of the i-th stack. Initially, all top[i] are set to the start of their respective segments minus one (indicating empty stacks).Push is done by incrementing top[i] and inserting the element, while pop is done by returning the element at top[i] and then decrementing it. Limitation: This approach leads to inefficient space utilization, since one stack may become full even when other stacks still have free space available.
            C++

    #include <iostream>
#include <vector>
using namespace std;

class kStacks {

    // main array to store elements
    int *arr;    

    // stores top index for each stack
    int *top;    

    // size of each segment
    int segSize; 

public:
    kStacks(int n, int k) {
        segSize = n / k;
        arr = new int[n];
        top = new int[k];

        // initialize top pointers
        for (int i = 0; i < k; i++)
            top[i] = i * segSize - 1;
    }

    // push element x into stack i
    void push(int x, int i) {
        int end = (i + 1) * segSize - 1;

        if (top[i] == end) {
            cout << "Stack " << i << " overflow" << endl;
            return;
        }

        top[i]++;
        arr[top[i]] = x;
    }

    // pop element from stack i
    int pop(int i) {
        int start = i * segSize;

        if (top[i] < start) {
            cout << "Stack " << i << " underflow" << endl;
            return -1;
        }

        int val = arr[top[i]];
        top[i]--;
        return val;
    }
};

int main() {
    int n = 4, k = 2;
    kStacks st(n, k);

    // Each operations has the following format:
    // 1. Push operation → {1, value, stackNumber}
    // 2. Pop operation  → {2, stackNumber}
    vector<vector<int>> operations = {
        {1, 5, 0},  
        {1, 9, 0},
        {1, 10, 0}, 
        {1, 15, 1}, 
        {2, 0},
        {2, 1},
        {2, 1}
    };

    for (auto &op : operations) {

        if (op[0] == 1) { 
            int x = op[1], m = op[2];
            st.push(x, m);
        } else if (op[0] == 2) { 
            int m = op[1];
            int res = st.pop(m);
            if (res != -1)
                cout << "Popped Element: " << res << endl;
        }
    }

    return 0;
}


